    /// Serves a `Server` on a connection (pass it in `CapSlot.export`).
    /// Inherited interfaces dispatch here too (the Server protocol inherits
    /// their requirements; E-order holds for the whole closure).
    public struct Export: ExportHandler {
        public let server: any Server
        public init(_ server: any Server) { self.server = server }
        public func handle(_ call: InboundCall, on connection: isolated RPCConnection) async throws -> CallResponse {
            switch call.interfaceID {
            case ChatService.interfaceID:
                switch call.methodID {
                case ChatService.Method.createRoom.rawValue:
                    let params = try decoding { try ChatService.CreateRoomParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.createRoom(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case ChatService.Method.joinRoom.rawValue:
                    let params = try decoding { try ChatService.JoinRoomParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.joinRoom(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case ChatService.Method.listRooms.rawValue:
                    let params = try decoding { try ChatService.ListRoomsParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.listRooms(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case ChatService.Method.whisper.rawValue:
                    let params = try decoding { try ChatService.WhisperParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.whisper(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                default:
                    throw RPCError.unimplemented(reason: "ChatService: no such method")
                }
            default:
                throw RPCError.unimplemented(reason: "ChatService: wrong interface")
            }
        }
    }

